import type { CategoryKey, CategoryMeta, CodeLanguage, Game, ModelId, ModFile } from "@/lib/types";
import { slugify } from "@/lib/data";

/*
 * Cyrus code-template engine.
 * Turns (game, category, mod name, prompt, model, version) into a plausible, deterministic
 * mod source tree for the game's real toolchain. Nothing here touches Math.random or the clock.
 */

export interface TemplateInput {
  game: Game;
  category: CategoryMeta;
  modName: string;
  prompt: string;
  model: ModelId;
  version: number;
}

// ---------------------------------------------------------------------------
// Deterministic randomness
// ---------------------------------------------------------------------------

function hashString(s: string): number {
  let h = 2166136261;
  for (let i = 0; i < s.length; i++) {
    h ^= s.charCodeAt(i);
    h = Math.imul(h, 16777619);
  }
  return h >>> 0;
}

function mulberry32(seed: number): () => number {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

class Rng {
  private next: () => number;
  constructor(seed: string) {
    this.next = mulberry32(hashString(seed));
  }
  float(min: number, max: number, dp = 1): number {
    const f = 10 ** dp;
    return Math.round((min + this.next() * (max - min)) * f) / f;
  }
  int(min: number, max: number, step = 1): number {
    const n = Math.floor((max - min) / step) + 1;
    return min + Math.floor(this.next() * n) * step;
  }
  pick<T>(arr: readonly T[]): T {
    return arr[Math.floor(this.next() * arr.length) % arr.length];
  }
  pickN<T>(arr: readonly T[], n: number): T[] {
    const pool = arr.slice();
    const out: T[] = [];
    while (out.length < n && pool.length) out.push(pool.splice(Math.floor(this.next() * pool.length), 1)[0]);
    return out;
  }
}

// ---------------------------------------------------------------------------
// Names, numbers and context
// ---------------------------------------------------------------------------

interface Names {
  display: string;
  pascal: string;
  camel: string;
  snake: string;
  kebab: string;
  upper: string;
  prefix: string;
}

function makeNames(modName: string): Names {
  const display = modName.trim() || "Cyrus Mod";
  let words = display.replace(/['’]/g, "").split(/[^A-Za-z0-9]+/).filter(Boolean);
  if (!words.length) words = ["Cyrus", "Mod"];
  if (/^[0-9]/.test(words[0])) words.unshift("Mod");
  const pascal = words.map((w) => w[0].toUpperCase() + w.slice(1)).join("");
  const snake = words.map((w) => w.toLowerCase()).join("_");
  let prefix = words.map((w) => w[0].toUpperCase()).join("").slice(0, 3);
  if (prefix.length < 2) prefix = pascal.slice(0, 3).toUpperCase();
  return {
    display,
    pascal,
    camel: pascal[0].toLowerCase() + pascal.slice(1),
    snake,
    kebab: slugify(display) || snake.replace(/_/g, "-"),
    upper: snake.toUpperCase(),
    prefix,
  };
}

interface Tune {
  dmg: number;
  atkSpeed: number;
  dur: number; // ticks (20/s)
  amp: number;
  power: number;
  radius: number;
  cooldown: number; // ticks
  chance: number; // 0..1
  health: number;
  weight: number;
  price: number;
  durability: number;
  speed: number;
  hue: [number, number, number];
}

function makeTune(rng: Rng): Tune {
  return {
    dmg: rng.int(6, 14),
    atkSpeed: rng.float(-3.0, -2.2, 1),
    dur: rng.int(60, 220, 10),
    amp: rng.int(0, 2),
    power: rng.float(3, 9, 1),
    radius: rng.int(3, 9),
    cooldown: rng.int(40, 240, 10),
    chance: rng.float(0.15, 0.45, 2),
    health: rng.int(4, 30) * 10,
    weight: rng.int(4, 30),
    price: rng.int(5, 90) * 10,
    durability: rng.int(6, 24) * 100,
    speed: rng.float(0.25, 0.4, 2),
    hue: [rng.float(0.2, 1, 2), rng.float(0.2, 1, 2), rng.float(0.2, 1, 2)],
  };
}

type Archetype = "hit" | "use" | "actor" | "system";

const ARCHETYPE: Record<CategoryKey, Archetype> = {
  weapons: "hit",
  items: "use",
  magic: "use",
  creatures: "actor",
  characters: "actor",
  vehicles: "actor",
  worlds: "system",
  mechanics: "system",
  quests: "system",
  interface: "system",
  audio: "system",
  shaders: "system",
};

interface Ctx {
  input: TemplateInput;
  n: Names;
  t: Tune;
  rng: Rng;
  cat: CategoryKey;
  arch: Archetype;
  text: string;
  intent: string;
  fx: Fx[];
  tier: 0 | 1 | 2;
  v: number;
  semver: string;
  vNote: string | null;
}

const TIER: Record<ModelId, 0 | 1 | 2> = { katara: 0, sokka: 1, yako: 2 };
const MODEL_NAME: Record<ModelId, string> = { katara: "Katara", sokka: "Sokka", yako: "Yako" };

function makeCtx(input: TemplateInput): Ctx {
  const v = Math.max(1, Math.floor(input.version || 1));
  const rng = new Rng(`${input.game.id}|${input.category.key}|${input.modName}|${v}`);
  const prompt = input.prompt.trim();
  const text = `${prompt} ${input.modName}`.toLowerCase();
  const t = makeTune(rng);
  const firstSentence = prompt.split(/(?<=[.!?])\s/)[0] ?? "";
  const intent = firstSentence
    ? firstSentence.replace(/\s+/g, " ").slice(0, 110)
    : `${input.modName} — a ${input.category.label.toLowerCase()} mod for ${input.game.name}`;
  return {
    input,
    n: makeNames(input.modName),
    t,
    rng,
    cat: input.category.key,
    arch: ARCHETYPE[input.category.key],
    text,
    intent,
    fx: matchEffects(text, input.category.key),
    tier: TIER[input.model],
    v,
    semver: `1.${v - 1}.0`,
    vNote: v > 1 ? versionNote(input, v) : null,
  };
}

function has(c: Ctx, ...words: string[]): boolean {
  return words.some((w) => new RegExp(`\\b${w}`).test(c.text));
}

const pct = (x: number) => Math.round(x * 100);
const secs = (ticks: number) => (ticks / 20).toFixed(1);

// ---------------------------------------------------------------------------
// Text helpers
// ---------------------------------------------------------------------------

function ind(lines: string[] | string, n: number): string {
  const arr = Array.isArray(lines) ? lines : lines.split("\n");
  const pad = " ".repeat(n);
  return arr.map((l) => (l.trim() ? pad + l : "")).join("\n");
}

const CLOSERS = /^(\}|end\b|End(If|Event|Function|While)\b|<\/)/;

/** Normalises whitespace: no trailing spaces, no doubled blank lines, no blank line hugging a brace. */
function finish(src: string): string {
  const raw = src.split("\n").map((l) => l.replace(/\s+$/, ""));
  const out: string[] = [];
  for (let i = 0; i < raw.length; i++) {
    const line = raw[i];
    if (line === "") {
      const prev = out[out.length - 1];
      const next = raw.slice(i + 1).find((l) => l !== "");
      if (prev === undefined || prev === "" || /[{(\[]$/.test(prev)) continue;
      if (next === undefined || CLOSERS.test(next.trim())) continue;
    }
    out.push(line);
  }
  return out.join("\n") + "\n";
}

function file(path: string, content: string): ModFile {
  return { path, language: languageForPath(path), content: finish(content) };
}

const json = (o: unknown) => JSON.stringify(o, null, 2);

export function languageForPath(path: string): CodeLanguage {
  const ext = path.toLowerCase().split(".").pop() ?? "";
  switch (ext) {
    case "java":
      return "java";
    case "psc":
      return "papyrus";
    case "cs":
      return "csharp";
    case "lua":
      return "lua";
    case "glsl":
    case "fsh":
    case "vsh":
      return "glsl";
    case "json":
      return "json";
    case "md":
      return "markdown";
    case "xml":
      return "xml";
    case "toml":
      return "toml";
    default:
      return "text";
  }
}

/** Short header comment shared by every main file; `cm` is the line-comment token. */
function header(c: Ctx, cm: string): string {
  const lines = [`${cm} ${c.n.display} · ${c.input.game.toolchain}`, `${cm} Intent: ${c.intent}`];
  if (c.vNote) lines.push(`${cm} v${c.v}: ${c.vNote}`);
  return lines.join("\n");
}

