  const lines = [`${cm} ${c.n.display} · ${c.input.game.toolchain}`, `${cm} Intent: ${c.intent}`];
  if (c.vNote) lines.push(`${cm} v${c.v}: ${c.vNote}`);
  return lines.join("\n");
}

