    tmlNpc: () => ["NPC.Center = target.Center + new Vector2(Main.rand.NextBool() ? -160f : 160f, -32f);", "NPC.netUpdate = true;"],
    sdv: () => ["who.Position = monster.Position + new Vector2(who.FacingDirection == 1 ? -64f : 64f, 0f);"],
    lua: () => ["Game.GetTeleportationFacility():Teleport(player, target:GetWorldPosition(), player:GetWorldOrientation():ToEulerAngles())"],
  },
  {
    key: "heal", words: ["heal", "regen", "restor", "mend", "cure", "bless", "life"],
    label: "Mending", blurb: "Restores health to the user", self: true,
