  {
    key: "poison", words: ["poison", "toxic", "venom", "acid", "plague", "blight"],
    label: "Venom", blurb: "Poisons targets over time", self: false,
    jimp: [`${SE}StatusEffectInstance`, `${SE}StatusEffects`],
    java: (v) => [`target.addStatusEffect(new StatusEffectInstance(StatusEffects.POISON, ${v.dur}, ${v.amp}), user);`],
    pprops: ["Spell Property PoisonCloakSpell Auto"], psc: ["PoisonCloakSpell.Cast(akCaster, akTarget)"],
    tml: (v) => [`target.AddBuff(BuffID.Venom, ${v.dur});`],
