    java: () => ["VexEntity echo = EntityType.VEX.create(world);", "if (echo != null) {", "    echo.refreshPositionAndAngles(target.getBlockPos().up(), user.getYaw(), 0.0F);", "    echo.setTarget(target);", "    world.spawnEntity(echo);", "}"],
    pprops: ["ActorBase Property SummonedEcho Auto"], psc: ["Actor kEcho = akTarget.PlaceActorAtMe(SummonedEcho)", "kEcho.StartCombat(akTarget)"],
    tml: (v) => [`Projectile.NewProjectile(player.GetSource_FromThis(), target.Center, Vector2.Zero, ProjectileID.SpectreWrath, ${v.pow}, 0f, player.whoAmI);`],
    tmlNpc: () => ["if (Main.netMode != NetmodeID.MultiplayerClient && NPC.CountNPCS(Type) < 4)", "    NPC.NewNPC(NPC.GetSource_FromAI(), (int)NPC.Center.X, (int)NPC.Center.Y, Type);"],
