    pprops: [], psc: ["akCaster.ApplyHavokImpulse(0.0, 0.0, 1.0, fPower * 10.0)"],
    tml: (v) => ["player.wingTime = player.wingTimeMax;", `player.velocity.Y = -${v.pow} / 4f;`],
