    tmlNpc: () => ["target.velocity += target.DirectionFrom(NPC.Center) * 9f;"],
    sdv: (v) => [`monster.takeDamage(${v.pow}, (int)(monster.Position.X - who.Position.X), (int)(monster.Position.Y - who.Position.Y), false, 0.0, who);`],
    lua: () => ['applyStatus(target, "BaseStatusEffect.Knockdown")'],
  },
];

const FALLBACK_FX: Record<CategoryKey, string> = {
  weapons: "force", creatures: "force", magic: "lightning", items: "heal", characters: "shield", vehicles: "speed",
  worlds: "glow", mechanics: "speed", quests: "heal", interface: "glow", audio: "glow", shaders: "glow",
};

function matchEffects(text: string, cat: CategoryKey): Fx[] {
  const hits = EFFECTS.filter((e) => e.words.some((w) => new RegExp(`\\b${w}`).test(text)));
  return hits.length ? hits.slice(0, 3) : EFFECTS.filter((e) => e.key === FALLBACK_FX[cat]);
}

const targetFx = (c: Ctx) => c.fx.filter((e) => !e.self);
const selfFx = (c: Ctx) => c.fx.filter((e) => e.self);
const fxNames = (c: Ctx) => c.fx.map((e) => e.label).join(" + ");

const VERSION_NOTES = [
  (t: Tune) => `retuned proc chance to ${pct(t.chance)}%`,
  (t: Tune) => `effect duration now ${t.dur} ticks (${secs(t.dur)}s)`,
  (t: Tune) => `cooldown rebalanced to ${t.cooldown} ticks`,
  (t: Tune) => `radius tightened to ${t.radius} blocks`,
  (t: Tune) => `power scaled to ${t.power}`,
  () => "guard against dead or despawned targets",
  () => "effects no longer stack on the same tick",
  () => "registration moved behind the config check",
];

function versionNote(input: TemplateInput, v: number): string {
  const rng = new Rng(`${input.game.id}|${input.category.key}|${input.modName}|${v}`);
  const t = makeTune(rng);
  const notes = new Rng(`notes|${input.modName}|${v}`).pickN(VERSION_NOTES, 2);
  return notes.map((f) => f(t)).join("; ");
}

