/** Per-effect presentation: [MC sound, MC Formatting, tML DustID]. */
const FX_STYLE: Record<string, [string, string, string]> = {
  frost: ["BLOCK_GLASS_BREAK", "AQUA", "IceTorch"],
  fire: ["ITEM_FIRECHARGE_USE", "GOLD", "Torch"],
  lightning: ["ENTITY_LIGHTNING_BOLT_IMPACT", "YELLOW", "Electric"],
  teleport: ["ENTITY_ENDERMAN_TELEPORT", "DARK_PURPLE", "PurpleTorch"],
  heal: ["ENTITY_PLAYER_LEVELUP", "GREEN", "HealingPlus"],
  poison: ["ENTITY_SPIDER_HURT", "DARK_GREEN", "Poisoned"],
  summon: ["ENTITY_EVOKER_PREPARE_SUMMON", "GRAY", "Shadowflame"],
  flight: ["ENTITY_PHANTOM_FLAP", "WHITE", "Cloud"],
  speed: ["ENTITY_BREEZE_WIND_BURST", "AQUA", "Smoke"],
  shield: ["ITEM_SHIELD_BLOCK", "BLUE", "Silver"],
  bleed: ["ENTITY_PLAYER_ATTACK_CRIT", "RED", "Blood"],
  glow: ["BLOCK_AMETHYST_BLOCK_CHIME", "LIGHT_PURPLE", "GemDiamond"],
  force: ["ENTITY_WARDEN_ATTACK_IMPACT", "DARK_RED", "Stone"],
};
const style = (c: Ctx) => FX_STYLE[c.fx[0].key];
const fxByKey = (key: string) => EFFECTS.find((e) => e.key === key) as Fx;
const selfOr = (c: Ctx, key: string) => (selfFx(c).length ? selfFx(c) : [fxByKey(key)]);
const isBoss = (c: Ctx) => has(c, "boss", "phase", "king", "monarch", "warden", "titan", "lord", "queen");
const hex6 = (c: Ctx) => c.t.hue.map((x) => Math.round(x * 255).toString(16).padStart(2, "0")).join("").toUpperCase();

// ---------------------------------------------------------------------------
// Minecraft · Fabric (Java 21)
// ---------------------------------------------------------------------------

function jv(c: Ctx): V {
  return c.tier
    ? { dur: "cfg.effectTicks", amp: "cfg.amplifier", pow: "cfg.power" }
    : { dur: `${c.t.dur}`, amp: `${c.t.amp}`, pow: `${c.t.power}F` };
}
const jfx = (c: Ctx, list: Fx[]) => list.flatMap((e) => e.java(jv(c)));
const jcfg = (c: Ctx) => (c.tier ? `        ${c.n.pascal}Config cfg = ${c.n.pascal}.CONFIG;` : "");
const jcd = (c: Ctx) => (c.tier ? "cfg.cooldownTicks" : `${c.t.cooldown}`);

function jimports(c: Ctx, base: string[], fx: Fx[] = c.fx): string {
  const pkg = `dev.cyrus.${c.n.snake}`;
  const extra = c.tier ? [`${pkg}.${c.n.pascal}`, `${pkg}.config.${c.n.pascal}Config`] : [];
  const all = [...new Set([...base, ...fx.flatMap((e) => e.jimp), ...extra])];
  const java = all.filter((i) => i.startsWith("java.")).sort();
  const rest = all.filter((i) => !i.startsWith("java.")).sort();
  return [...rest.map((i) => `import ${i};`), ...(java.length ? ["", ...java.map((i) => `import ${i};`)] : [])].join("\n");
}

interface JavaPart {
  path: string;
  content: string;
  mainImports: string[];
  fields: string;
  init: string[];
}

const MC = "net.minecraft.";

function javaHit(c: Ctx): JavaPart {
  const { n, t } = c;
  const P = n.pascal;
  const [sound, fmt] = style(c);
  const imports = jimports(c, [`${MC}entity.LivingEntity`, `${MC}item.Item`, `${MC}item.ItemStack`, `${MC}item.SwordItem`, `${MC}item.ToolMaterial`,
    `${MC}item.tooltip.TooltipType`, `${MC}sound.SoundCategory`, `${MC}sound.SoundEvents`, `${MC}text.Text`, `${MC}util.Formatting`, `${MC}world.World`,
    "java.util.List", ...(c.tier ? [`${MC}entity.player.PlayerEntity`] : [])]);
  const guard = c.tier === 2
    ? `        if (user instanceof PlayerEntity player && player.getItemCooldownManager().isCoolingDown(this)) {
            return super.postHit(stack, target, user);
        }`
    : "";
  const cooldown = c.tier
    ? `            if (user instanceof PlayerEntity player) {
                player.getItemCooldownManager().set(this, ${jcd(c)});
            }`
    : "";
  const content = `package dev.cyrus.${n.snake}.item;

${imports}

/**
 * ${n.display}: ${fxNames(c)} on critical hits.
${c.tier === 2 ? ` *
 * <p>Procs on vanilla crits or on a flat chance roll, then goes on a short cooldown so
 * sweeping attacks cannot chain the effect across a whole crowd.</p>\n` : ""} */
public class ${P}Item extends SwordItem {
    public ${P}Item(ToolMaterial material, Item.Settings settings) {
        super(material, settings);
    }

    @Override
    public boolean postHit(ItemStack stack, LivingEntity target, LivingEntity user) {
        World world = user.getWorld();
        if (world.isClient() || !target.isAlive()) {
            return super.postHit(stack, target, user);
        }
${guard}
${jcfg(c)}
        // Vanilla crit rule (falling, airborne, not climbing) plus a flat proc so it never feels binary.
        boolean critical = user.fallDistance > 0.0F && !user.isOnGround() && !user.isClimbing();
        if (critical || world.random.nextFloat() < ${c.tier ? "cfg.procChance" : `${t.chance}F`}) {
${ind(jfx(c, c.fx), 12)}
            world.playSound(null, target.getBlockPos(), SoundEvents.${sound}, SoundCategory.PLAYERS, 0.8F, 1.2F);
${cooldown}
        }
        return super.postHit(stack, target, user);
    }

    @Override
    public void appendTooltip(ItemStack stack, Item.TooltipContext context, List<Text> tooltip, TooltipType type) {
        tooltip.add(Text.translatable("item.${n.snake}.${n.snake}.tooltip").formatted(Formatting.${fmt}));
    }
}
`;
  return {
    path: `item/${P}Item.java`,
    content,
    mainImports: [`dev.cyrus.${n.snake}.item.${P}Item`, `${MC}item.Item`, `${MC}item.ItemGroups`, `${MC}item.SwordItem`, `${MC}item.ToolMaterials`, `${MC}util.Rarity`, "net.fabricmc.fabric.api.itemgroup.v1.ItemGroupEvents"],
    fields: `    public static final Item ${n.upper} = Registry.register(
            Registries.ITEM,
            id("${n.snake}"),
            new ${P}Item(ToolMaterials.NETHERITE, new Item.Settings()
                    .attributeModifiers(SwordItem.createAttributeModifiers(ToolMaterials.NETHERITE, ${t.dmg}, ${t.atkSpeed}F))
                    .rarity(Rarity.EPIC)));`,
    init: [`ItemGroupEvents.modifyEntriesEvent(ItemGroups.COMBAT).register(entries -> entries.add(${n.upper}));`],
  };
}

function javaUse(c: Ctx): JavaPart {
  const { n, t } = c;
  const P = n.pascal;
  const tfx = targetFx(c);
  const magic = c.cat === "magic";
  const imports = jimports(c, [`${MC}entity.LivingEntity`, `${MC}entity.player.PlayerEntity`, `${MC}item.Item`, `${MC}item.ItemStack`,
    `${MC}sound.SoundCategory`, `${MC}sound.SoundEvents`, `${MC}util.Hand`, `${MC}util.TypedActionResult`, `${MC}world.World`,
    ...(tfx.length ? [`${MC}util.math.Box`, "java.util.List"] : [])]);
  const area = tfx.length
    ? `        // ${magic ? "Cast" : "Pulse"} hits everything living within ${t.radius} blocks except the user.
        Box area = user.getBoundingBox().expand(${c.tier ? "cfg.radius" : `${t.radius}.0`});
        List<LivingEntity> targets = world.getEntitiesByClass(LivingEntity.class, area, e -> e != user && e.isAlive());
        for (LivingEntity target : targets) {
${ind(jfx(c, tfx), 12)}
        }`
    : "";
  const content = `package dev.cyrus.${n.snake}.item;

${imports}

/**
 * ${n.display}: right-click to ${magic ? "cast" : "use"} ${fxNames(c)}.
 */
public class ${P}Item extends Item {
    public ${P}Item(Item.Settings settings) {
        super(settings);
    }

    @Override
    public TypedActionResult<ItemStack> use(World world, PlayerEntity user, Hand hand) {
        ItemStack stack = user.getStackInHand(hand);
        if (world.isClient()) {
            return TypedActionResult.success(stack);
        }
${c.tier === 2 ? `        if (user.isSpectator() || stack.getDamage() >= stack.getMaxDamage() - 1) {
            return TypedActionResult.fail(stack);
        }` : ""}
${jcfg(c)}
${area}
${ind(jfx(c, selfFx(c)), 8)}
        world.playSound(null, user.getBlockPos(), SoundEvents.${style(c)[0]}, SoundCategory.PLAYERS, 1.0F, 1.0F);
        user.getItemCooldownManager().set(this, ${jcd(c)});
        stack.damage(1, user, LivingEntity.getSlotForHand(hand));
        return TypedActionResult.consume(stack);
    }
}
`;
  return {
    path: `item/${P}Item.java`,
    content,
    mainImports: [`dev.cyrus.${n.snake}.item.${P}Item`, `${MC}item.Item`, `${MC}item.ItemGroups`, `${MC}util.Rarity`, "net.fabricmc.fabric.api.itemgroup.v1.ItemGroupEvents"],
    fields: `    public static final Item ${n.upper} = Registry.register(
            Registries.ITEM,
            id("${n.snake}"),
            new ${P}Item(new Item.Settings().maxDamage(${t.durability}).rarity(Rarity.${magic ? "EPIC" : "RARE"})));`,
    init: [`ItemGroupEvents.modifyEntriesEvent(ItemGroups.${magic ? "COMBAT" : "TOOLS"}).register(entries -> entries.add(${n.upper}));`],
  };
}

function javaActor(c: Ctx): JavaPart {
  const { n, t } = c;
  const P = n.pascal;
  const kind = c.cat;
  const boss = kind === "creatures" && isBoss(c);
  const base = kind === "creatures" ? "HostileEntity" : "PathAwareEntity";
  const group = kind === "creatures" ? "MONSTER" : kind === "characters" ? "CREATURE" : "MISC";
  const self = selfOr(c, kind === "vehicles" ? "speed" : "shield");
  const tfx = kind === "vehicles" ? [] : kind === "characters" ? targetFx(c) : c.fx;
  const SEI = [`${MC}entity.effect.StatusEffectInstance`, `${MC}entity.effect.StatusEffects`];
  const imp = [`${MC}entity.EntityType`, `${MC}entity.LivingEntity`, `${MC}entity.attribute.DefaultAttributeContainer`, `${MC}entity.attribute.EntityAttributes`,
    `${MC}entity.ai.goal.SwimGoal`, `${MC}entity.ai.goal.LookAroundGoal`, `${MC}entity.mob.${base}`, `${MC}entity.player.PlayerEntity`, `${MC}world.World`];
  if (kind !== "vehicles") imp.push(`${MC}entity.ai.goal.MeleeAttackGoal`, `${MC}entity.ai.goal.WanderAroundFarGoal`, `${MC}entity.ai.goal.LookAtEntityGoal`, `${MC}entity.ai.goal.RevengeGoal`);
  if (tfx.length) imp.push(`${MC}entity.Entity`);
  if (kind === "creatures") imp.push(`${MC}entity.ai.goal.ActiveTargetGoal`);
  if (boss) imp.push(`${MC}entity.boss.BossBar`, `${MC}entity.boss.ServerBossBar`, `${MC}server.network.ServerPlayerEntity`, `${MC}sound.SoundEvents`);
  if (kind === "characters") imp.push(`${MC}entity.ai.goal.TemptGoal`, `${MC}item.Items`, `${MC}recipe.Ingredient`, `${MC}text.Text`, `${MC}util.ActionResult`, `${MC}util.Hand`);
  if (kind === "vehicles") imp.push(`${MC}util.ActionResult`, `${MC}util.Hand`, `${MC}util.math.Vec3d`);
  const goals = kind === "creatures"
    ? ["this.goalSelector.add(1, new SwimGoal(this));", "this.goalSelector.add(2, new MeleeAttackGoal(this, 1.1, false));", "this.goalSelector.add(5, new WanderAroundFarGoal(this, 0.8));",
      "this.goalSelector.add(6, new LookAtEntityGoal(this, PlayerEntity.class, 8.0F));", "this.goalSelector.add(7, new LookAroundGoal(this));",
      "this.targetSelector.add(1, new RevengeGoal(this));", "this.targetSelector.add(2, new ActiveTargetGoal<>(this, PlayerEntity.class, true));"]
    : kind === "characters"
      ? ["this.goalSelector.add(1, new SwimGoal(this));", "this.goalSelector.add(2, new MeleeAttackGoal(this, 1.0, true));",
        "this.goalSelector.add(3, new TemptGoal(this, 1.0, Ingredient.ofItems(Items.EMERALD), false));", "this.goalSelector.add(6, new WanderAroundFarGoal(this, 0.6));",
        "this.goalSelector.add(7, new LookAtEntityGoal(this, PlayerEntity.class, 6.0F));", "this.targetSelector.add(1, new RevengeGoal(this));"]
      : ["this.goalSelector.add(1, new SwimGoal(this));", "this.goalSelector.add(8, new LookAroundGoal(this));"];
  const attack = tfx.length
    ? `
    @Override
    public boolean tryAttack(Entity entity) {
        boolean hit = super.tryAttack(entity);
        if (!hit || !(entity instanceof LivingEntity target) || this.getWorld().isClient()) {
            return hit;
        }
        World world = this.getWorld();
        LivingEntity user = this;
${jcfg(c)}
${ind(jfx(c, tfx), 8)}
        return true;
    }
`
    : "";
  const bossBlock = boss
    ? `
    @Override
    protected void mobTick() {
        super.mobTick();
        this.bossBar.setPercent(this.getHealth() / this.getMaxHealth());
        // Phase two at half health: faster and louder, so players feel the shift.
        if (!this.phaseTwo && this.getHealth() < this.getMaxHealth() * 0.5F) {
            this.phaseTwo = true;
            this.bossBar.setColor(BossBar.Color.RED);
            this.getAttributeInstance(EntityAttributes.GENERIC_MOVEMENT_SPEED).setBaseValue(${(t.speed * 1.4).toFixed(2)});
            this.playSound(SoundEvents.ENTITY_WARDEN_ROAR, 2.0F, 0.8F);
        }
    }

    @Override
    public void onStartedTrackingBy(ServerPlayerEntity player) {
        super.onStartedTrackingBy(player);
        this.bossBar.addPlayer(player);
    }

    @Override
