        player.sendMessage(Text.translatable("entity.${n.snake}.${n.snake}.greeting." + this.random.nextInt(3)), false);
        // A small blessing on a cooldown: companions should feel helpful, not spammy.
        if (this.blessingCooldown <= 0) {
            LivingEntity user = player;
${jcfg(c)}
${ind(jfx(c, self), 12)}
            this.blessingCooldown = ${jcd(c)};
