function javaConfig(c: Ctx): string {
  const { n, t } = c;
  const P = n.pascal;
  return `package dev.cyrus.${n.snake}.config;

import com.google.gson.Gson;
import com.google.gson.GsonBuilder;
import net.fabricmc.loader.api.FabricLoader;

import java.io.IOException;
import java.io.Reader;
import java.io.Writer;
import java.nio.file.Files;
import java.nio.file.Path;

/** Plain GSON config at config/${n.snake}.json, created with defaults on first launch. */
public final class ${P}Config {
    private static final Gson GSON = new GsonBuilder().setPrettyPrinting().create();
    private static final Path FILE = FabricLoader.getInstance().getConfigDir().resolve("${n.snake}.json");

    public boolean enabled = true;
    public int effectTicks = ${t.dur};
    public int amplifier = ${t.amp};
    public float power = ${t.power}F;
    public double radius = ${t.radius}.0;
    public int cooldownTicks = ${t.cooldown};
    public float procChance = ${t.chance}F;

    public static ${P}Config load() {
        if (Files.exists(FILE)) {
            try (Reader reader = Files.newBufferedReader(FILE)) {
                ${P}Config cfg = GSON.fromJson(reader, ${P}Config.class);
                if (cfg != null) {
                    return cfg.clamp();
                }
            } catch (IOException | RuntimeException e) {
                // A broken config should never crash the game; fall back to defaults below.
            }
        }
        ${P}Config defaults = new ${P}Config();
        defaults.save();
        return defaults;
    }

    public void save() {
        try (Writer writer = Files.newBufferedWriter(FILE)) {
            GSON.toJson(this, writer);
        } catch (IOException ignored) {
        }
    }

    ${P}Config clamp() {
        effectTicks = Math.max(1, effectTicks);
        amplifier = Math.clamp(amplifier, 0, 4);
        procChance = Math.clamp(procChance, 0.0F, 1.0F);
        cooldownTicks = Math.max(0, cooldownTicks);
        return this;
    }
}
`;
}

function javaTest(c: Ctx): string {
  const { n } = c;
  const P = n.pascal;
  return `package dev.cyrus.${n.snake};

import dev.cyrus.${n.snake}.config.${P}Config;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;

class ${P}Test {
    @Test
    void modIdIsValidForFabric() {
        assertTrue(${P}.MOD_ID.matches("[a-z][a-z0-9_-]{1,63}"));
    }

    @Test
    void defaultsAreSane() {
        ${P}Config cfg = new ${P}Config();
        assertTrue(cfg.effectTicks > 0);
        assertTrue(cfg.procChance > 0.0F && cfg.procChance <= 1.0F);
        assertTrue(cfg.radius >= 1.0);
    }

    @Test
    void clampRepairsHandEditedValues() {
        ${P}Config cfg = new ${P}Config();
        cfg.procChance = 7.5F;
        cfg.amplifier = -3;
        cfg.clamp();
        assertEquals(1.0F, cfg.procChance);
        assertEquals(0, cfg.amplifier);
    }
}
`;
}

