      init: [`BiomeModifications.addFeature(BiomeSelectors.foundInOverworld(), GenerationStep.Feature.${cave ? "UNDERGROUND_DECORATION" : sky ? "SURFACE_STRUCTURES" : "VEGETAL_DECORATION"}, ${n.upper}_PLACED);`],
    };
  }
  if (c.cat === "interface") {
    const extraLine = has(c, "map", "minimap", "compass", "waypoint")
      ? `        context.drawTextWithShadow(font, Text.translatable("hud.${n.snake}.facing", client.player.getHorizontalFacing().asString()), x, y + 36, 0xFFAAAAAA);`
      : `        long time = client.world == null ? 0L : client.world.getTimeOfDay() % 24000L;
        context.drawTextWithShadow(font, Text.translatable("hud.${n.snake}.time", time / 1000L), x, y + 36, 0xFFAAAAAA);`;
    const content = `package ${pkg}.client;

${jimports(c, ["net.fabricmc.fabric.api.client.rendering.v1.HudRenderCallback", `${MC}client.MinecraftClient`, `${MC}client.font.TextRenderer`,
    `${MC}client.gui.DrawContext`, `${MC}client.render.RenderTickCounter`, `${MC}text.Text`, `${MC}util.math.BlockPos`], [])}

/**
 * ${n.display}: lightweight HUD overlay, drawn after vanilla so it never fights the hotbar.
 */
public class ${P}Hud implements HudRenderCallback {
    private static final int ACCENT = 0xFF${hex6(c)};
