        TextRenderer font = client.textRenderer;
        int x = ${c.rng.int(4, 12)};
        int y = ${c.rng.int(4, 12)};
        float health = client.player.getHealth() / client.player.getMaxHealth();
        context.fill(x, y, x + 102, y + 8, PANEL);
        context.fill(x + 1, y + 1, x + 1 + (int) (100 * health), y + 7, ACCENT);
        context.drawTextWithShadow(font, Text.translatable("hud.${n.snake}.title"), x, y + 12, ACCENT);
        BlockPos pos = client.player.getBlockPos();
