    return { path: `client/${P}Hud.java`, content, mainImports: [`${pkg}.client.${P}Hud`, "net.fabricmc.fabric.api.client.rendering.v1.HudRenderCallback"], fields: "", init: [`HudRenderCallback.EVENT.register(new ${P}Hud());`] };
