    body = `    public enum Stage { NOT_STARTED, ${stages.join(", ")}, COMPLETE }

    private static final Map<UUID, Stage> PROGRESS = new HashMap<>();
    private static final Map<UUID, Integer> KILLS = new HashMap<>();

