    const inner = farming
      ? `            // Harvest mature crops around the player and replant them at age 0.
            for (BlockPos pos : BlockPos.iterateOutwards(player.getBlockPos(), ${t.radius}, 1, ${t.radius})) {
                BlockState state = world.getBlockState(pos);
