${farming ? "" : "        ServerPlayConnectionEvents.DISCONNECT.register((handler, server) -> COOLDOWNS.remove(handler.getPlayer().getUuid()));"}
    }

    private static void onWorldTick(ServerWorld world) {
        // Runs every ${interval} ticks, not every tick: plenty responsive, much cheaper.
