        assertTrue(${P}.MOD_ID.matches("[a-z][a-z0-9_-]{1,63}"));
    }

    @Test
    void defaultsAreSane() {
        ${P}Config cfg = new ${P}Config();
        assertTrue(cfg.effectTicks > 0);
        assertTrue(cfg.procChance > 0.0F && cfg.procChance <= 1.0F);
        assertTrue(cfg.radius >= 1.0);
