`),
    ],
    config: file("shaders/lib/settings.glsl", `// ${c.n.display} · tweakables. [bracketed] values become sliders in the shader menu.\n\n${defs.join("\n")}\n`),
    l10n: file("shaders/lang/en_US.lang", lang),
    extras: [],
  };
}

