/** Drops unused / same-package Java imports so liberal import lists stay tidy. */
function pruneJavaImports(src: string): string {
  const pkg = /^package ([\w.]+);/m.exec(src)?.[1] ?? "";
  const body = src.replace(/^import .*$/gm, "");
  return src
    .split("\n")
    .filter((line) => {
      const m = /^import ([\w.]+)\.(\w+);$/.exec(line);
      if (!m) return true;
      return m[1] !== pkg && new RegExp(`\\b${m[2]}\\b`).test(body);
    })
    .join("\n")
    .replace(/\n{3,}/g, "\n\n");
}

interface Bundle {
  core: ModFile[];
  config: ModFile;
  l10n: ModFile | null;
  extras: ModFile[];
}

function minecraftBundle(c: Ctx): Bundle {
  const { n } = c;
  if (c.cat === "shaders") return minecraftShaders(c);
  const root = `src/main/java/dev/cyrus/${n.snake}`;
  const part = c.arch === "hit" ? javaHit(c) : c.arch === "use" ? javaUse(c) : c.arch === "actor" ? javaActor(c) : javaSystem(c);
  const jfile = (path: string, src: string) => file(path, pruneJavaImports(src));
  const lang: Record<string, string> = {};
  if (c.arch === "hit" || c.arch === "use") {
    lang[`item.${n.snake}.${n.snake}`] = n.display;
    lang[`item.${n.snake}.${n.snake}.tooltip`] = `${fxNames(c)}: ${c.fx.map((e) => e.blurb.toLowerCase()).join(", ")}`;
  } else if (c.arch === "actor") {
    lang[`entity.${n.snake}.${n.snake}`] = n.display;
    if (c.cat === "characters") ["Well met, traveler.", "The road is quieter with company.", "Need a hand? I am listening."].forEach((s, i) => (lang[`entity.${n.snake}.${n.snake}.greeting.${i}`] = s));
  } else if (c.cat === "quests") {
    lang[`quest.${n.snake}.start`] = `${n.display} has begun.`;
    lang[`quest.${n.snake}.stage.complete`] = `${n.display} complete!`;
  } else if (c.cat === "interface") {
    Object.assign(lang, { [`hud.${n.snake}.title`]: n.display, [`hud.${n.snake}.facing`]: "Facing %s", [`hud.${n.snake}.time`]: "Hour %s" });
  } else if (c.cat === "audio") {
    Object.assign(lang, { [`subtitles.${n.snake}.theme`]: `${n.display} plays`, [`subtitles.${n.snake}.stinger`]: "Music swells" });
  } else {
    lang[`${n.snake}.name`] = n.display;
  }
  const modJson = {
    schemaVersion: 1,
    id: n.snake,
    version: c.semver,
    name: n.display,
    description: c.intent,
    authors: ["Cyrus"],
    contact: { sources: `https://github.com/cyrus-mods/${n.kebab}` },
    license: "MIT",
    icon: `assets/${n.snake}/icon.png`,
    environment: c.cat === "interface" ? "client" : "*",
    entrypoints: { [c.cat === "interface" ? "client" : "main"]: [`dev.cyrus.${n.snake}.${n.pascal}`] },
    depends: { fabricloader: ">=0.16.0", minecraft: "~1.21.1", java: ">=21", "fabric-api": "*" },
  };
  return {
    core: [jfile(`${root}/${n.pascal}.java`, javaMain(c, part)), jfile(`${root}/${part.path}`, part.content), file("src/main/resources/fabric.mod.json", json(modJson))],
    config: jfile(`${root}/config/${n.pascal}Config.java`, javaConfig(c)),
    l10n: file(`src/main/resources/assets/${n.snake}/lang/en_us.json`, json(lang)),
    extras: [jfile(`src/test/java/dev/cyrus/${n.snake}/${n.pascal}Test.java`, javaTest(c))],
  };
}

// ---------------------------------------------------------------------------
// GLSL post-processing (Iris composite pass, or a ReShade-style pass for CET)
// ---------------------------------------------------------------------------

interface ShaderFlags {
  fog: boolean;
  sky: boolean;
  rain: boolean;
  bloom: boolean;
  grade: boolean;
}

function shaderFlags(c: Ctx): ShaderFlags {
  const f = {
    fog: has(c, "fog", "mist", "haze", "volumetric", "shaft"),
    sky: has(c, "sky", "skies", "nebula", "star", "aurora", "night", "cosmic", "galaxy"),
    rain: has(c, "rain", "wet", "reflect", "puddle", "slick"),
    bloom: has(c, "bloom", "glow", "neon", "light"),
    grade: has(c, "color", "colour", "grade", "grading", "synthwave", "film", "tone", "teal", "cinematic", "lut"),
  };
  if (!Object.values(f).some(Boolean)) f.grade = f.bloom = true;
  return f;
}

function glslDefines(c: Ctx, f: ShaderFlags): string[] {
  const r = c.rng;
  const opt = (name: string, v: number, dp = 2) => {
    const steps = [0.5, 1, 1.5, 2].map((k) => (v * k).toFixed(dp)).join(" ");
    return `#define ${name} ${v.toFixed(dp)} // [${steps}]`;
  };
  const vec = (a: number[]) => `vec3(${a.map((x) => x.toFixed(2)).join(", ")})`;
  const [h0, h1, h2] = c.t.hue;
  const out: string[] = [];
  if (f.fog) out.push(opt("FOG_DENSITY", r.float(0.01, 0.05, 3), 3), `#define FOG_COLOR ${vec([0.55 + h0 * 0.2, 0.6 + h1 * 0.2, 0.7 + h2 * 0.2])}`);
  if (f.sky) out.push(opt("STAR_DENSITY", r.float(0.002, 0.008, 4), 4), opt("NEBULA_STRENGTH", r.float(0.3, 0.8, 2)), `#define NEBULA_A ${vec([h0 * 0.5, 0.1, h2])}`, `#define NEBULA_B ${vec([h2, h1 * 0.4, 0.6])}`);
  if (f.rain) out.push(opt("REFLECTION_STRENGTH", r.float(0.3, 0.7, 2)));
  if (f.bloom) out.push(opt("BLOOM_STRENGTH", r.float(0.4, 1.2, 2)), opt("BLOOM_THRESHOLD", r.float(0.6, 0.85, 2)));
  if (f.grade) out.push(opt("GRADE_STRENGTH", r.float(0.25, 0.6, 2)), opt("FILM_GRAIN", r.float(0.01, 0.05, 3), 3), `#define SHADOW_TINT ${vec([0.05, 0.35 + h1 * 0.2, 0.45])}`, `#define HIGHLIGHT_TINT ${vec([1.0, 0.45 + h0 * 0.2, 0.75])}`);
  out.push(opt("VIGNETTE", r.float(0.2, 0.5, 2)));
  return out;
}

function glslFragment(c: Ctx, target: "iris" | "reshade", includeSettings: boolean): string {
  const f = shaderFlags(c);
  const iris = target === "iris";
  const TEX = iris ? "colortex0" : "BackBuffer";
  const DEPTH = iris ? "depthtex0" : "DepthBuffer";
  const uniforms = iris
    ? ["uniform sampler2D colortex0;", "uniform sampler2D depthtex0;", "uniform float frameTimeCounter;", "uniform float rainStrength;", "uniform float viewWidth;", "uniform float viewHeight;"]
    : ["uniform sampler2D BackBuffer;", "uniform sampler2D DepthBuffer;", "uniform float Timer;       // ms", "uniform float RainAmount;  // pushed from init.lua", "uniform vec2 ScreenSize;"];
  const fns: string[] = [];
  const calls: string[] = [];
  if (f.sky) {
    fns.push(`// Nebula and stars are only drawn where depth says "sky", so terrain stays untouched.
vec3 applySky(vec3 color, vec2 uv, vec2 res, float time) {
    float n = fbm(uv * 2.5 + vec2(time * 0.005, -time * 0.003));
    vec3 nebula = mix(NEBULA_A, NEBULA_B, smoothstep(0.35, 0.75, n)) * n * NEBULA_STRENGTH;
    float star = step(1.0 - STAR_DENSITY, hash12(floor(uv * res * 0.5)));
    float twinkle = 0.6 + 0.4 * sin(time * 3.0 + hash12(uv) * 40.0);
    return color + nebula + vec3(star * twinkle);
}`);
    calls.push("if (isSky) {", "    color = applySky(color, uv, res, time);", "}");
  }
  if (f.fog) {
    fns.push(`float linearDepth(float d) {
    const float near = 0.05;
    const float far = 256.0;
    return (2.0 * near * far) / (far + near - (d * 2.0 - 1.0) * (far - near));
}

// Exponential distance fog with slow-drifting noise so valleys breathe instead of sitting flat.
vec3 applyFog(vec3 color, float depth, vec2 uv, float time) {
    float drift = fbm(uv * 3.0 + vec2(time * 0.02, 0.0));
    float amount = 1.0 - exp(-linearDepth(depth) * FOG_DENSITY * (0.7 + 0.6 * drift));
    return mix(color, FOG_COLOR, clamp(amount, 0.0, 1.0));
}`);
    calls.push("if (!isSky) {", "    color = applyFog(color, depth, uv, time);", "}");
  }
  if (f.rain) {
    fns.push(`// Cheap screen-space "reflection": mirror the frame below the horizon and wobble it with ripples.
vec3 applyWetSurfaces(vec3 color, vec2 uv, float wetness, float time) {
    if (uv.y > 0.5 || wetness <= 0.0) {
        return color;
    }
    float ripple = (valueNoise(uv * 120.0 + time * 4.0) - 0.5) * 0.006;
    vec3 mirrored = texture(${TEX}, vec2(uv.x + ripple, 1.0 - uv.y)).rgb;
    float fresnel = pow(1.0 - uv.y * 2.0, 3.0);
    return mix(color, mirrored, fresnel * wetness * REFLECTION_STRENGTH);
}`);
    calls.push(`color = applyWetSurfaces(color, uv, ${iris ? "rainStrength" : "RainAmount"}, time);`);
  }
  if (f.bloom) {
    fns.push(`vec3 applyBloom(vec3 color, vec2 uv, vec2 texel) {
    vec3 glow = vec3(0.0);
    for (int x = -2; x <= 2; x++) {
        for (int y = -2; y <= 2; y++) {
            vec3 s = texture(${TEX}, uv + vec2(x, y) * texel * 3.0).rgb;
            glow += max(s - vec3(BLOOM_THRESHOLD), vec3(0.0));
        }
    }
    return color + glow / 25.0 * BLOOM_STRENGTH;
}`);
    calls.push("color = applyBloom(color, uv, 1.0 / res);");
  }
  if (f.grade) {
    fns.push(`// Split-tone grade: shadows lean toward SHADOW_TINT, highlights toward HIGHLIGHT_TINT.
vec3 applyGrade(vec3 color, vec2 uv, float time) {
    float luma = dot(color, vec3(0.2126, 0.7152, 0.0722));
    vec3 graded = mix(SHADOW_TINT, HIGHLIGHT_TINT, smoothstep(0.0, 1.0, luma)) * luma * 2.0;
    color = mix(color, graded, GRADE_STRENGTH);
    float grain = (hash12(uv * 1024.0 + fract(time) * 100.0) - 0.5) * FILM_GRAIN;
    return color + grain;
}`);
    calls.push("color = applyGrade(color, uv, time);");
  }
  const settings = includeSettings ? ['#include "/lib/settings.glsl"'] : glslDefines(c, f);
  return `#version 330 ${iris ? "compatibility" : "core"}
${header(c, "//")}

${settings.join("\n")}

${uniforms.join("\n")}

in vec2 texcoord;

${iris ? "/* RENDERTARGETS: 0 */\nlayout(location = 0) out vec4 fragColor;" : "out vec4 fragColor;"}

float hash12(vec2 p) {
    vec3 p3 = fract(vec3(p.xyx) * 0.1031);
    p3 += dot(p3, p3.yzx + 33.33);
    return fract((p3.x + p3.y) * p3.z);
}

float valueNoise(vec2 p) {
    vec2 i = floor(p);
    vec2 f = fract(p);
    vec2 u = f * f * (3.0 - 2.0 * f);
    return mix(mix(hash12(i), hash12(i + vec2(1.0, 0.0)), u.x),
               mix(hash12(i + vec2(0.0, 1.0)), hash12(i + vec2(1.0, 1.0)), u.x), u.y);
}

float fbm(vec2 p) {
    float sum = 0.0;
    float amp = 0.5;
    for (int i = 0; i < 5; i++) {
        sum += amp * valueNoise(p);
        p = p * 2.03 + vec2(17.0, 9.0);
        amp *= 0.5;
    }
    return sum;
}

vec3 acesTonemap(vec3 x) {
    return clamp((x * (2.51 * x + 0.03)) / (x * (2.43 * x + 0.59) + 0.14), 0.0, 1.0);
}

${fns.join("\n\n")}

void main() {
    vec2 uv = texcoord;
    vec2 res = ${iris ? "vec2(viewWidth, viewHeight)" : "ScreenSize"};
    float time = ${iris ? "frameTimeCounter" : "Timer * 0.001"};
    vec3 color = texture(${TEX}, uv).rgb;
    float depth = texture(${DEPTH}, uv).r;
    bool isSky = depth >= 1.0;

${ind(calls, 4)}

    float vignette = smoothstep(0.95, 0.35, length(uv - 0.5));
    color *= mix(1.0, vignette, VIGNETTE);
    fragColor = vec4(acesTonemap(color), 1.0);
}
`;
}

function minecraftShaders(c: Ctx): Bundle {
