screen.ATMOSPHERE=${atmosphere.join(" ") || "<empty>"}
screen.POST=${post.join(" ")}
sliders=${names.join(" ")}

profile.LOW=${post.map((x) => `${x}=${x === "VIGNETTE" ? "0.20" : "0.50"}`).join(" ")}
profile.HIGH=
`;
  const lang = names.map((x) => `option.${x}=${pretty(x)}`).join("\n") + `\nprofile.comment=${c.n.display} presets\n`;
  return {
    core: [
      file("shaders/program/composite.fsh", glslFragment(c, "iris", c.tier > 0)),
      file("shaders/shaders.properties", props),
      file("shaders/program/composite.vsh", `#version 330 compatibility

out vec2 texcoord;

void main() {
    gl_Position = ftransform();
    texcoord = (gl_TextureMatrix[0] * gl_MultiTexCoord0).xy;
}
`),
    ],
    config: file("shaders/lib/settings.glsl", `// ${c.n.display} · tweakables. [bracketed] values become sliders in the shader menu.\n\n${defs.join("\n")}\n`),
    l10n: file("shaders/lang/en_US.lang", lang),
    extras: [],
  };
}
